const std = @import("std");

const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;

const TensorError = error{
    ShapeMismatch,
    InvalidAxis,
    EmptyAxis,
    BroadcastIncompatible,
    InvalidShape,
    InvalidReshape,
    InvalidAxes,
    InvalidRanges,
    InvalidSlice,
    EmptyConcat,
    EmptyStack,
    InvalidReps,
    InvalidPads,
    ZeroStep,
    InvalidForVariance,
    InvalidForOneHot,
};

const Tensor = struct {
    allocator: Allocator,
    data: []f32,
    shape: []usize,
    strides: []usize,
    ndim: usize,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        if (shape.len == 0) return TensorError.InvalidShape;
        var self: Tensor = .{
            .allocator = allocator,
            .shape = try allocator.dupe(usize, shape),
            .strides = try allocator.alloc(usize, shape.len),
            .data = undefined,
            .ndim = shape.len,
        };
        var size: usize = 1;
        var i: usize = shape.len;
        while (i > 0) {
            i -= 1;
            self.strides[i] = size;
            if (shape[i] == 0) {
                try self.deinitErr();
                return TensorError.InvalidShape;
            }
            size = math.mul(usize, size, shape[i]) catch {
                try self.deinitErr();
                return TensorError.InvalidShape;
            };
        }
        self.data = try allocator.alloc(f32, size);
        for (self.data) |*x| x.* = 0.0;
        return self;
    }

    fn deinitErr(self: *Tensor) !void {
        if (self.data.len != 0) self.allocator.free(self.data);
        if (self.shape.len != 0) self.allocator.free(self.shape);
        if (self.strides.len != 0) self.allocator.free(self.strides);
        self.data = &[_]f32{}.*;
        self.shape = &[_]usize{}.*;
        self.strides = &[_]usize{}.*;
        self.ndim = 0;
    }

    pub fn deinit(self: *Tensor) void {
        if (self.data.len != 0) self.allocator.free(self.data);
        if (self.shape.len != 0) self.allocator.free(self.shape);
        if (self.strides.len != 0) self.allocator.free(self.strides);
    }

    pub fn copy(self: *const Tensor, allocator: Allocator) !Tensor {
        var new = try init(allocator, self.shape);
        @memcpy(new.data, self.data);
        return new;
    }

    pub fn fill(self: *Tensor, value: f32) void {
        for (self.data) |*x| x.* = value;
    }

    inline fn indexUnchecked(self: *const Tensor, indices: []const usize) usize {
        var idx: usize = 0;
        var k: usize = 0;
        while (k < self.ndim) : (k += 1) {
            idx += indices[k] * self.strides[k];
        }
        return idx;
    }

    pub fn getIndex(self: *const Tensor, indices: []const usize) usize {
        var idx: usize = 0;
        var k: usize = 0;
        while (k < self.ndim) : (k += 1) {
            std.debug.assert(indices[k] < self.shape[k]);
            idx += indices[k] * self.strides[k];
        }
        return idx;
    }

    pub fn get(self: *const Tensor, indices: []const usize) f32 {
        return self.data[self.getIndex(indices)];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f32) void {
        self.data[self.getIndex(indices)] = value;
    }

    pub fn add(self: *Tensor, other: *const Tensor) TensorError!void {
        if (self.ndim != other.ndim or !mem.eql(usize, self.shape, other.shape)) return TensorError.ShapeMismatch;
        var i: usize = 0;
        const n = self.data.len;
        while (i < n) : (i += 1) {
            self.data[i] += other.data[i];
        }
    }

    pub fn sub(self: *Tensor, other: *const Tensor) TensorError!void {
        if (self.ndim != other.ndim or !mem.eql(usize, self.shape, other.shape)) return TensorError.ShapeMismatch;
        var i: usize = 0;
        const n = self.data.len;
        while (i < n) : (i += 1) {
            self.data[i] -= other.data[i];
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor) TensorError!void {
        if (self.ndim != other.ndim or !mem.eql(usize, self.shape, other.shape)) return TensorError.ShapeMismatch;
        var i: usize = 0;
        const n = self.data.len;
        while (i < n) : (i += 1) {
            self.data[i] *= other.data[i];
        }
    }

    pub fn div(self: *Tensor, other: *const Tensor) TensorError!void {
        if (self.ndim != other.ndim or !mem.eql(usize, self.shape, other.shape)) return TensorError.ShapeMismatch;
        var i: usize = 0;
        const n = self.data.len;
        while (i < n) : (i += 1) {
            self.data[i] /= other.data[i];
        }
    }

    pub fn addScalar(self: *Tensor, scalar: f32) void {
        for (self.data) |*x| x.* += scalar;
    }

    pub fn subScalar(self: *Tensor, scalar: f32) void {
        for (self.data) |*x| x.* -= scalar;
    }

    pub fn mulScalar(self: *Tensor, scalar: f32) void {
        for (self.data) |*x| x.* *= scalar;
    }

    pub fn divScalar(self: *Tensor, scalar: f32) void {
        for (self.data) |*x| x.* /= scalar;
    }

    pub fn exp(self: *Tensor) void {
        for (self.data) |*x| x.* = math.exp(x.*);
    }

    pub fn log(self: *Tensor) void {
        for (self.data) |*x| x.* = math.log(x.*);
    }

    pub fn sin(self: *Tensor) void {
        for (self.data) |*x| x.* = math.sin(x.*);
    }

    pub fn cos(self: *Tensor) void {
        for (self.data) |*x| x.* = math.cos(x.*);
    }

    pub fn tan(self: *Tensor) void {
        for (self.data) |*x| x.* = math.tan(x.*);
    }

    pub fn sqrt(self: *Tensor) void {
        for (self.data) |*x| x.* = math.sqrt(x.*);
    }

    pub fn pow(self: *Tensor, expn: f32) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            self.data[i] = math.pow(f32, self.data[i], expn);
        }
    }

    pub fn abs(self: *Tensor) void {
        for (self.data) |*x| x.* = math.fabs(x.*);
    }

    pub fn max(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var best: f32 = -math.inf(f32);
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                const idx = off + j * self.strides[axis];
                best = if (self.data[idx] > best) self.data[idx] else best;
            }
            var out_idx: usize = 0;
            k = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) out_idx += base_idx[k] * out.strides[k];
            out.data[out_idx] = best;
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn min(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var best: f32 = math.inf(f32);
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                const idx = off + j * self.strides[axis];
                best = if (self.data[idx] < best) self.data[idx] else best;
            }
            var out_idx: usize = 0;
            k = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) out_idx += base_idx[k] * out.strides[k];
            out.data[out_idx] = best;
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn sum(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var acc: f32 = 0.0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                const idx = off + j * self.strides[axis];
                acc += self.data[idx];
            }
            var out_idx: usize = 0;
            k = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) out_idx += base_idx[k] * out.strides[k];
            out.data[out_idx] = acc;
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn mean(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var s = try self.sum(allocator, axis);
        defer s.deinit();
        const divv = @as(f32, @floatFromInt(self.shape[axis]));
        s.divScalar(divv);
        return try s.copy(allocator);
    }

    pub fn variance(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] <= 1) return TensorError.InvalidForVariance;
        var m = try self.mean(allocator, axis);
        defer m.deinit();
        var diff = try self.copy(allocator);
        defer diff.deinit();
        var b_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(b_shape);
        b_shape[axis] = 1;
        var b_mean = try m.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try diff.sub(&b_mean);
        var sq = try diff.copy(allocator);
        defer sq.deinit();
        try sq.mul(&sq);
        var v = try sq.sum(allocator, axis);
        defer v.deinit();
        const n = @as(f32, @floatFromInt(self.shape[axis]));
        v.divScalar(n - 1.0);
        return try v.copy(allocator);
    }

    pub fn stddev(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        var v = try self.variance(allocator, axis);
        defer v.deinit();
        v.sqrt();
        return try v.copy(allocator);
    }

    pub fn argmax(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var best: f32 = -math.inf(f32);
            var best_i: usize = 0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                const idx = off + j * self.strides[axis];
                const val = self.data[idx];
                if (val > best) {
                    best = val;
                    best_i = j;
                }
            }
            var out_idx: usize = 0;
            k = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) out_idx += base_idx[k] * out.strides[k];
            out.data[out_idx] = @as(f32, @floatFromInt(best_i));
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn argmin(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var best: f32 = math.inf(f32);
            var best_i: usize = 0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                const idx = off + j * self.strides[axis];
                const val = self.data[idx];
                if (val < best) {
                    best = val;
                    best_i = j;
                }
            }
            var out_idx: usize = 0;
            k = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) out_idx += base_idx[k] * out.strides[k];
            out.data[out_idx] = @as(f32, @floatFromInt(best_i));
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn broadcast(self: *const Tensor, allocator: Allocator, target_shape: []const usize) TensorError!Tensor {
        if (self.ndim != target_shape.len) return TensorError.ShapeMismatch;
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) {
            const s1 = self.shape[i];
            const s2 = target_shape[i];
            if (!(s1 == s2 or s1 == 1 or s2 == 1)) return TensorError.BroadcastIncompatible;
        }
        var out = try init(allocator, target_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) {
                src_idx[i] = if (self.shape[i] == 1) 0 else idx[i] % self.shape[i];
            }
            const v = self.get(src_idx);
            out.set(idx, v);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) TensorError!void {
        var new_size: usize = 1;
        for (new_shape) |s| {
            if (s == 0) return TensorError.InvalidShape;
            new_size = math.mul(usize, new_size, s) catch return TensorError.InvalidShape;
        }
        if (new_size != self.data.len) return TensorError.InvalidReshape;
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
        self.ndim = new_shape.len;
        var stride: usize = 1;
        var i: usize = self.ndim;
        while (i > 0) {
            i -= 1;
            self.strides[i] = stride;
            stride = math.mul(usize, stride, new_shape[i]) catch return TensorError.InvalidShape;
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator, axes: []const usize) TensorError!Tensor {
        if (axes.len != self.ndim) return TensorError.InvalidAxes;
        var seen = try allocator.alloc(bool, self.ndim);
        defer allocator.free(seen);
        for (seen) |*b| b.* = false;
        for (axes) |ax| {
            if (ax >= self.ndim or seen[ax]) return TensorError.InvalidAxes;
            seen[ax] = true;
        }
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) new_shape[i] = self.shape[axes[i]];
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) src_idx[axes[i]] = idx[i];
            const val = self.get(src_idx);
            out.set(idx, val);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn slice(self: *const Tensor, allocator: Allocator, ranges: []const [2]usize) TensorError!Tensor {
        if (ranges.len != self.ndim) return TensorError.InvalidRanges;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) {
            const r = ranges[i];
            if (r[0] > r[1] or r[1] > self.shape[i]) return TensorError.InvalidSlice;
            new_shape[i] = r[1] - r[0];
        }
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) src_idx[i] = idx[i] + ranges[i][0];
            const val = self.get(src_idx);
            out.set(idx, val);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn concatenate(allocator: Allocator, tensors: []const Tensor, axis: usize) TensorError!Tensor {
        if (tensors.len == 0) return TensorError.EmptyConcat;
        const ndim = tensors[0].ndim;
        if (axis >= ndim) return TensorError.InvalidAxis;
        const base_shape = tensors[0].shape;
        var t: usize = 0;
        while (t < tensors.len) : (t += 1) {
            if (tensors[t].ndim != ndim) return TensorError.ShapeMismatch;
            var d: usize = 0;
            while (d < ndim) : (d += 1) {
                if (d != axis and tensors[t].shape[d] != base_shape[d]) return TensorError.ShapeMismatch;
            }
        }
        var new_shape = try allocator.dupe(usize, base_shape);
        defer allocator.free(new_shape);
        t = 1;
        while (t < tensors.len) : (t += 1) {
            new_shape[axis] += tensors[t].shape[axis];
        }
        var out = try init(allocator, new_shape);
        var offset_axis: usize = 0;
        var idx = try allocator.alloc(usize, ndim);
        defer allocator.free(idx);
        var local = try allocator.alloc(usize, ndim);
        defer allocator.free(local);
        t = 0;
        while (t < tensors.len) : (t += 1) {
            const ten = tensors[t];
            var k: usize = 0;
            while (k < ndim) : (k += 1) {
                idx[k] = 0;
                local[k] = 0;
            }
            while (true) {
                var copy_idx = idx;
                copy_idx[axis] = offset_axis + idx[axis];
                const val = ten.get(idx);
                out.set(copy_idx, val);
                var carry = true;
                var j: usize = ndim;
                while (carry and j > 0) {
                    j -= 1;
                    idx[j] += 1;
                    if (idx[j] < ten.shape[j]) {
                        carry = false;
                    } else {
                        idx[j] = 0;
                    }
                }
                if (carry) break;
            }
            offset_axis += ten.shape[axis];
        }
        return out;
    }

    pub fn stack(allocator: Allocator, tensors: []const Tensor, axis: usize) TensorError!Tensor {
        if (tensors.len == 0) return TensorError.EmptyStack;
        const ndim = tensors[0].ndim;
        if (axis > ndim) return TensorError.InvalidAxis;
        var t: usize = 0;
        while (t < tensors.len) : (t += 1) {
