    pub fn exp(self: *Tensor) void {
        for (self.data) |*x| x.* = math.exp(x.*);
    }

    pub fn log(self: *Tensor) void {
        for (self.data) |*x| x.* = math.log(x.*);
    }

    pub fn sin(self: *Tensor) void {
        for (self.data) |*x| x.* = math.sin(x.*);
    }

    pub fn cos(self: *Tensor) void {
        for (self.data) |*x| x.* = math.cos(x.*);
    }

    pub fn tan(self: *Tensor) void {
        for (self.data) |*x| x.* = math.tan(x.*);
    }

    pub fn sqrt(self: *Tensor) void {
        for (self.data) |*x| x.* = math.sqrt(x.*);
    }

    pub fn pow(self: *Tensor, expn: f32) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            self.data[i] = math.pow(f32, self.data[i], expn);
        }
    }

    pub fn abs(self: *Tensor) void {
        for (self.data) |*x| x.* = math.fabs(x.*);
    }

    pub fn max(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
