    pub fn broadcast(self: *const Tensor, allocator: Allocator, target_shape: []const usize) TensorError!Tensor {
        if (self.ndim != target_shape.len) return TensorError.ShapeMismatch;
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) {
            const s1 = self.shape[i];
            const s2 = target_shape[i];
            if (!(s1 == s2 or s1 == 1 or s2 == 1)) return TensorError.BroadcastIncompatible;
        }
        var out = try init(allocator, target_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) {
                src_idx[i] = if (self.shape[i] == 1) 0 else idx[i] % self.shape[i];
            }
            const v = self.get(src_idx);
            out.set(idx, v);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) TensorError!void {
        var new_size: usize = 1;
        for (new_shape) |s| {
            if (s == 0) return TensorError.InvalidShape;
            new_size = math.mul(usize, new_size, s) catch return TensorError.InvalidShape;
        }
        if (new_size != self.data.len) return TensorError.InvalidReshape;
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
        self.ndim = new_shape.len;
        var stride: usize = 1;
        var i: usize = self.ndim;
        while (i > 0) {
            i -= 1;
            self.strides[i] = stride;
            stride = math.mul(usize, stride, new_shape[i]) catch return TensorError.InvalidShape;
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator, axes: []const usize) TensorError!Tensor {
        if (axes.len != self.ndim) return TensorError.InvalidAxes;
        var seen = try allocator.alloc(bool, self.ndim);
        defer allocator.free(seen);
        for (seen) |*b| b.* = false;
        for (axes) |ax| {
            if (ax >= self.ndim or seen[ax]) return TensorError.InvalidAxes;
            seen[ax] = true;
        }
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) new_shape[i] = self.shape[axes[i]];
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) src_idx[axes[i]] = idx[i];
            const val = self.get(src_idx);
            out.set(idx, val);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn slice(self: *const Tensor, allocator: Allocator, ranges: []const [2]usize) TensorError!Tensor {
        if (ranges.len != self.ndim) return TensorError.InvalidRanges;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) {
            const r = ranges[i];
            if (r[0] > r[1] or r[1] > self.shape[i]) return TensorError.InvalidSlice;
            new_shape[i] = r[1] - r[0];
        }
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) src_idx[i] = idx[i] + ranges[i][0];
            const val = self.get(src_idx);
            out.set(idx, val);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn concatenate(allocator: Allocator, tensors: []const Tensor, axis: usize) TensorError!Tensor {
        if (tensors.len == 0) return TensorError.EmptyConcat;
        const ndim = tensors[0].ndim;
        if (axis >= ndim) return TensorError.InvalidAxis;
        const base_shape = tensors[0].shape;
        var t: usize = 0;
        while (t < tensors.len) : (t += 1) {
            if (tensors[t].ndim != ndim) return TensorError.ShapeMismatch;
            var d: usize = 0;
            while (d < ndim) : (d += 1) {
                if (d != axis and tensors[t].shape[d] != base_shape[d]) return TensorError.ShapeMismatch;
            }
        }
        var new_shape = try allocator.dupe(usize, base_shape);
        defer allocator.free(new_shape);
        t = 1;
        while (t < tensors.len) : (t += 1) {
            new_shape[axis] += tensors[t].shape[axis];
        }
        var out = try init(allocator, new_shape);
        var offset_axis: usize = 0;
        var idx = try allocator.alloc(usize, ndim);
        defer allocator.free(idx);
        var local = try allocator.alloc(usize, ndim);
        defer allocator.free(local);
        t = 0;
        while (t < tensors.len) : (t += 1) {
            const ten = tensors[t];
            var k: usize = 0;
            while (k < ndim) : (k += 1) {
                idx[k] = 0;
                local[k] = 0;
            }
            while (true) {
                var copy_idx = idx;
                copy_idx[axis] = offset_axis + idx[axis];
                const val = ten.get(idx);
                out.set(copy_idx, val);
                var carry = true;
                var j: usize = ndim;
                while (carry and j > 0) {
                    j -= 1;
                    idx[j] += 1;
                    if (idx[j] < ten.shape[j]) {
                        carry = false;
                    } else {
                        idx[j] = 0;
                    }
                }
                if (carry) break;
            }
            offset_axis += ten.shape[axis];
        }
        return out;
    }

    pub fn stack(allocator: Allocator, tensors: []const Tensor, axis: usize) TensorError!Tensor {
        if (tensors.len == 0) return TensorError.EmptyStack;
        const ndim = tensors[0].ndim;
        if (axis > ndim) return TensorError.InvalidAxis;
        var t: usize = 0;
        while (t < tensors.len) : (t += 1) {
            if (tensors[t].ndim != ndim or !mem.eql(usize, tensors[t].shape, tensors[0].shape)) return TensorError.ShapeMismatch;
        }
        var new_shape = try allocator.alloc(usize, ndim + 1);
        defer allocator.free(new_shape);
        var k: usize = 0;
        var i: usize = 0;
        while (i < ndim + 1) : (i += 1) {
            if (i == axis) {
                new_shape[i] = tensors.len;
            } else {
                new_shape[i] = tensors[0].shape[k];
                k += 1;
            }
        }
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, ndim + 1);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var local = try allocator.alloc(usize, ndim);
        defer allocator.free(local);
        while (true) {
            const ten_idx = idx[axis];
            var l: usize = 0;
            i = 0;
            while (i < ndim + 1) : (i += 1) {
                if (i != axis) {
                    local[l] = idx[i];
                    l += 1;
                }
            }
            const val = tensors[ten_idx].get(local);
            out.set(idx, val);
            var carry = true;
            var j: usize = ndim + 1;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn tile(self: *const Tensor, allocator: Allocator, reps: []const usize) TensorError!Tensor {
        if (reps.len != self.ndim) return TensorError.InvalidReps;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
