        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) {
                src[i] = idx[i] % self.shape[i];
            }
            const v = self.get(src);
            out.set(idx, v);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
