            const val = self.get(src_idx);
            out.set(idx, val);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn slice(self: *const Tensor, allocator: Allocator, ranges: []const [2]usize) TensorError!Tensor {
        if (ranges.len != self.ndim) return TensorError.InvalidRanges;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) {
            const r = ranges[i];
            if (r[0] > r[1] or r[1] > self.shape[i]) return TensorError.InvalidSlice;
            new_shape[i] = r[1] - r[0];
        }
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src_idx);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) src_idx[i] = idx[i] + ranges[i][0];
            const val = self.get(src_idx);
            out.set(idx, val);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn concatenate(allocator: Allocator, tensors: []const Tensor, axis: usize) TensorError!Tensor {
        if (tensors.len == 0) return TensorError.EmptyConcat;
        const ndim = tensors[0].ndim;
        if (axis >= ndim) return TensorError.InvalidAxis;
        const base_shape = tensors[0].shape;
        var t: usize = 0;
        while (t < tensors.len) : (t += 1) {
            if (tensors[t].ndim != ndim) return TensorError.ShapeMismatch;
            var d: usize = 0;
            while (d < ndim) : (d += 1) {
                if (d != axis and tensors[t].shape[d] != base_shape[d]) return TensorError.ShapeMismatch;
            }
        }
        var new_shape = try allocator.dupe(usize, base_shape);
        defer allocator.free(new_shape);
        t = 1;
        while (t < tensors.len) : (t += 1) {
            new_shape[axis] += tensors[t].shape[axis];
        }
        var out = try init(allocator, new_shape);
        var offset_axis: usize = 0;
        var idx = try allocator.alloc(usize, ndim);
        defer allocator.free(idx);
        var copy_idx = try allocator.alloc(usize, ndim);
        defer allocator.free(copy_idx);
        t = 0;
        while (t < tensors.len) : (t += 1) {
            const ten = tensors[t];
            var k: usize = 0;
            while (k < ndim) : (k += 1) {
                idx[k] = 0;
            }
            while (true) {
                k = 0;
                while (k < ndim) : (k += 1) copy_idx[k] = idx[k];
                copy_idx[axis] = offset_axis + idx[axis];
                const val = ten.get(idx);
                out.set(copy_idx, val);
                var carry = true;
                var j: usize = ndim;
                while (carry and j > 0) {
                    j -= 1;
                    idx[j] += 1;
                    if (idx[j] < ten.shape[j]) {
                        carry = false;
                    } else {
                        idx[j] = 0;
                    }
                }
                if (carry) break;
            }
            offset_axis += ten.shape[axis];
        }
        return out;
    }

    pub fn stack(allocator: Allocator, tensors: []const Tensor, axis: usize) TensorError!Tensor {
        if (tensors.len == 0) return TensorError.EmptyStack;
        const ndim = tensors[0].ndim;
        if (axis > ndim) return TensorError.InvalidAxis;
        var t: usize = 0;
        while (t < tensors.len) : (t += 1) {
            if (tensors[t].ndim != ndim or !mem.eql(usize, tensors[t].shape, tensors[0].shape)) return TensorError.ShapeMismatch;
        }
        var new_shape = try allocator.alloc(usize, ndim + 1);
        defer allocator.free(new_shape);
        var k: usize = 0;
        var i: usize = 0;
        while (i < ndim + 1) : (i += 1) {
            if (i == axis) {
                new_shape[i] = tensors.len;
            } else {
                new_shape[i] = tensors[0].shape[k];
                k += 1;
            }
        }
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, ndim + 1);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var local = try allocator.alloc(usize, ndim);
        defer allocator.free(local);
        while (true) {
            const ten_idx = idx[axis];
            var l: usize = 0;
            i = 0;
            while (i < ndim + 1) : (i += 1) {
                if (i != axis) {
                    local[l] = idx[i];
                    l += 1;
                }
            }
            const val = tensors[ten_idx].get(local);
            out.set(idx, val);
            var carry = true;
            var j: usize = ndim + 1;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn tile(self: *const Tensor, allocator: Allocator, reps: []const usize) TensorError!Tensor {
        if (reps.len != self.ndim) return TensorError.InvalidReps;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) new_shape[i] = self.shape[i] * reps[i];
        var out = try init(allocator, new_shape);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src);
        while (true) {
            i = 0;
            while (i < self.ndim) : (i += 1) {
                src[i] = idx[i] % self.shape[i];
            }
            const v = self.get(src);
            out.set(idx, v);
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn pad(self: *const Tensor, allocator: Allocator, pads: []const [2]usize) TensorError!Tensor {
        if (pads.len != self.ndim) return TensorError.InvalidPads;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.ndim) : (i += 1) {
            new_shape[i] = self.shape[i] + pads[i][0] + pads[i][1];
        }
        var out = try init(allocator, new_shape);
        out.fill(0.0);
        var idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(idx);
        for (idx) |*v| v.* = 0;
        var src = try allocator.alloc(usize, self.ndim);
        defer allocator.free(src);
        while (true) {
            var in_range = true;
            i = 0;
            while (i < self.ndim) : (i += 1) {
                const pi = pads[i][0];
                const s = self.shape[i];
                if (idx[i] < pi or idx[i] >= pi + s) {
                    in_range = false;
                } else {
                    src[i] = idx[i] - pi;
                }
            }
            if (in_range) {
                const v = self.get(src);
                out.set(idx, v);
            }
            var carry = true;
            var j: usize = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                idx[j] += 1;
                if (idx[j] < out.shape[j]) {
                    carry = false;
                } else {
                    idx[j] = 0;
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn clip(self: *Tensor, min_val: f32, max_val: f32) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            self.data[i] = math.clamp(self.data[i], min_val, max_val);
        }
    }

    pub fn normalize(self: *Tensor, allocator: Allocator, axis: usize, epsilon: f32) TensorError!void {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var mean_t = try self.mean(allocator, axis);
        defer mean_t.deinit();
        var var_t = try self.variance(allocator, axis);
        defer var_t.deinit();
        var_t.addScalar(epsilon);
        var_t.sqrt();
        var b_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(b_shape);
        b_shape[axis] = 1;
        var b_mean = try mean_t.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try self.sub(&b_mean);
        var b_std = try var_t.broadcast(allocator, b_shape);
        defer b_std.deinit();
        try self.div(&b_std);
    }

    pub fn oneHot(self: *const Tensor, allocator: Allocator, num_classes: usize) TensorError!Tensor {
        if (self.ndim != 1) return TensorError.InvalidForOneHot;
        var new_shape = [_]usize{ self.shape[0], num_classes };
        var out = try init(allocator, &new_shape);
        out.fill(0.0);
        var i: usize = 0;
        while (i < self.shape[0]) : (i += 1) {
            const v = self.get(&.{ i });
            if (math.isFinite(v) and v >= 0.0 and v < @as(f32, @floatFromInt(num_classes))) {
                const vf = math.floor(v);
                if (vf == v) {
                    const cls: usize = @intFromFloat(v);
                    out.set(&.{ i, cls }, 1.0);
                }
            }
        }
        return out;
    }

    pub fn cumsum(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var out = try self.copy(allocator);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var j: usize = 1;
            while (j < self.shape[axis]) : (j += 1) {
                const prev = off + (j - 1) * self.strides[axis];
                const curr = off + j * self.strides[axis];
                out.data[curr] = out.data[curr] + out.data[prev];
            }
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

